insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('a8d85716-2953-4854-ae9e-3730b916231d', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', null, 'topic'::public.curated_course_node_type, 'Science as a Way of Knowing', 'This opening unit frames natural science as a disciplined way of asking questions about the physical, chemical, biological, and Earth systems around us. Students learn that science is not a list of facts; it is a method for building, testing, revising, and communicating explanations.', 0),
  ('b2a1e4c2-a850-4561-a0f8-98dd9306af9f', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'a8d85716-2953-4854-ae9e-3730b916231d', 'subtopic'::public.curated_course_node_type, 'Observation, inference, and explanation', 'Students learn to separate what is directly observed from the interpretations and models built from those observations.', 0),
  ('e6c4adf6-11cc-4e74-b8d2-3c25b1034145', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'b2a1e4c2-a850-4561-a0f8-98dd9306af9f', 'concept'::public.curated_course_node_type, 'Qualitative and quantitative observations', null, 0),
  ('2be70b78-1b88-4d70-aae0-05a0cd472fea', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'b2a1e4c2-a850-4561-a0f8-98dd9306af9f', 'concept'::public.curated_course_node_type, 'Inference versus assumption', null, 1),
  ('c0571489-96b9-4c0c-8013-462c48ab56f4', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'b2a1e4c2-a850-4561-a0f8-98dd9306af9f', 'concept'::public.curated_course_node_type, 'Evidence-based explanation', null, 2),
  ('7053c5b9-19d0-4cba-a099-354b4b1348d5', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'a8d85716-2953-4854-ae9e-3730b916231d', 'subtopic'::public.curated_course_node_type, 'The scientific method and scientific inquiry', 'This subtopic introduces the cycle of questioning, prediction, testing, analysis, and revision used across laboratory sciences.', 1),
  ('2851f60f-1fc2-4eb0-913b-506ed1f4d336', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '7053c5b9-19d0-4cba-a099-354b4b1348d5', 'concept'::public.curated_course_node_type, 'Questions and hypotheses', null, 0),
  ('ae70a99c-abed-4e72-87be-3768859429aa', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '7053c5b9-19d0-4cba-a099-354b4b1348d5', 'concept'::public.curated_course_node_type, 'Prediction and testability', null, 1),
  ('ca590bb5-ef1a-4ede-93e6-d183aee11a60', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '7053c5b9-19d0-4cba-a099-354b4b1348d5', 'concept'::public.curated_course_node_type, 'Iteration and revision', null, 2),
  ('7b43adc7-9606-4201-a5d1-aff00c5d6595', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'a8d85716-2953-4854-ae9e-3730b916231d', 'subtopic'::public.curated_course_node_type, 'Scientific literacy and source evaluation', 'Students practice reading scientific claims carefully, identifying credible sources, and recognizing uncertainty in public science communication.', 2),
  ('915edbe3-64cd-4ed3-b353-dce8f351b1dc', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '7b43adc7-9606-4201-a5d1-aff00c5d6595', 'concept'::public.curated_course_node_type, 'Peer review and authority', null, 0),
  ('6f081c34-cb35-4ecc-9b15-38c12cce05db', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '7b43adc7-9606-4201-a5d1-aff00c5d6595', 'concept'::public.curated_course_node_type, 'Correlation, causation, and overclaiming', null, 1),
  ('637a0913-e93c-4fda-aa63-e80a6c445380', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '7b43adc7-9606-4201-a5d1-aff00c5d6595', 'concept'::public.curated_course_node_type, 'Science news and misinformation', null, 2),
  ('f97911e6-26a4-446a-ab80-b1a7c5293822', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', null, 'topic'::public.curated_course_node_type, 'Measurement, Units, Uncertainty, and Significant Figures', 'Laboratory science depends on careful measurement. This unit gives students the habits needed to collect data that are meaningful, comparable, and honest about their limits.', 1),
  ('b03e72c0-b55d-4027-9c2d-df735d27c7ad', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'f97911e6-26a4-446a-ab80-b1a7c5293822', 'subtopic'::public.curated_course_node_type, 'Units and dimensional reasoning', 'Students learn to use SI units, unit conversions, dimensional analysis, and scale reasoning as basic tools for scientific problem solving.', 0),
  ('6f8c86b8-fe4f-40c0-a4b3-94639f677bae', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'b03e72c0-b55d-4027-9c2d-df735d27c7ad', 'concept'::public.curated_course_node_type, 'SI base and derived units', null, 0),
  ('ab09423b-3387-4583-ac32-b1466b61ba61', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'b03e72c0-b55d-4027-9c2d-df735d27c7ad', 'concept'::public.curated_course_node_type, 'Unit conversion and dimensional checks', null, 1),
  ('54900379-2db3-4f2d-931a-81a24f99db15', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'b03e72c0-b55d-4027-9c2d-df735d27c7ad', 'concept'::public.curated_course_node_type, 'Orders of magnitude and scale', null, 2),
  ('cd31ca29-d5f9-4fcc-b4eb-de91131dd6c0', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'f97911e6-26a4-446a-ab80-b1a7c5293822', 'subtopic'::public.curated_course_node_type, 'Accuracy, precision, and uncertainty', 'This subtopic teaches students to distinguish closeness to the true value from repeatability, and to communicate uncertainty appropriately.', 1),
  ('01e87790-8ba5-4fe2-8c54-779e47c849a1', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'cd31ca29-d5f9-4fcc-b4eb-de91131dd6c0', 'concept'::public.curated_course_node_type, 'Systematic and random error', null, 0),
  ('9af4e36f-0422-4c8b-bda1-60c3d0ddbf81', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'cd31ca29-d5f9-4fcc-b4eb-de91131dd6c0', 'concept'::public.curated_course_node_type, 'Instrument resolution', null, 1),
  ('f940aaf5-9227-40a9-8c92-c1d722f91171', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'cd31ca29-d5f9-4fcc-b4eb-de91131dd6c0', 'concept'::public.curated_course_node_type, 'Uncertainty intervals', null, 2),
  ('ec597121-a78c-48c6-a3f9-3b6674082a19', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'f97911e6-26a4-446a-ab80-b1a7c5293822', 'subtopic'::public.curated_course_node_type, 'Significant figures and scientific notation', 'Students learn how reported numbers carry information about measurement quality and how to avoid false precision.', 2),
  ('d9c72aa8-9c13-4e78-add7-306e23ec6de9', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'ec597121-a78c-48c6-a3f9-3b6674082a19', 'concept'::public.curated_course_node_type, 'Rounding rules', null, 0),
  ('c5724b93-17d4-466e-97fe-ab316dce0deb', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'ec597121-a78c-48c6-a3f9-3b6674082a19', 'concept'::public.curated_course_node_type, 'Propagation in simple calculations', null, 1),
  ('3a6d6230-75b2-4fd1-a7aa-00e1a006799f', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'ec597121-a78c-48c6-a3f9-3b6674082a19', 'concept'::public.curated_course_node_type, 'Scientific notation in lab records', null, 2),
  ('59eb633b-17b2-41e8-9d5b-c3fc7b365819', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', null, 'topic'::public.curated_course_node_type, 'Laboratory Safety, Ethics, and Scientific Responsibility', 'This lab course treats safety and ethics as core scientific skills. Students learn how to protect themselves, classmates, organisms, communities, and the integrity of the evidence they produce.', 2),
  ('9218b0f5-c2e6-4fe9-9107-6ed813a08016', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '59eb633b-17b2-41e8-9d5b-c3fc7b365819', 'subtopic'::public.curated_course_node_type, 'Safety culture and hazard recognition', 'Students learn to identify physical, chemical, biological, and environmental hazards before beginning any experiment.', 0),
  ('5fa4ce3d-1994-4ec4-b080-c8569edc0edf', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '9218b0f5-c2e6-4fe9-9107-6ed813a08016', 'concept'::public.curated_course_node_type, 'Safety Data Sheets', null, 0),
  ('8aad9f44-0774-4bcf-9ca8-9d161a2b9bf4', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '9218b0f5-c2e6-4fe9-9107-6ed813a08016', 'concept'::public.curated_course_node_type, 'PPE and engineering controls', null, 1),
  ('17683a89-7019-4e3f-a6e0-e28bcfeed473', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '9218b0f5-c2e6-4fe9-9107-6ed813a08016', 'concept'::public.curated_course_node_type, 'Emergency response basics', null, 2),
  ('ffc27d55-9877-4f2f-a532-36ee6a11f004', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '59eb633b-17b2-41e8-9d5b-c3fc7b365819', 'subtopic'::public.curated_course_node_type, 'Ethical conduct in the laboratory', 'This subtopic introduces honesty in data recording, responsible collaboration, respect for living systems, and appropriate handling of uncertainty.', 1),
  ('3256e356-9838-4e64-97af-c557fc1ea0cd', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'ffc27d55-9877-4f2f-a532-36ee6a11f004', 'concept'::public.curated_course_node_type, 'Data integrity', null, 0),
  ('9ba1d008-06e5-4b7f-ae6c-3f1d4e9dc38f', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'ffc27d55-9877-4f2f-a532-36ee6a11f004', 'concept'::public.curated_course_node_type, 'Authorship and collaboration', null, 1),
  ('e322cf40-ac6e-4a6f-aa0a-a66702593ef7', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'ffc27d55-9877-4f2f-a532-36ee6a11f004', 'concept'::public.curated_course_node_type, 'Animal, human, and environmental considerations', null, 2),
  ('8c62a132-f8f0-417b-8101-92c17387fd82', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '59eb633b-17b2-41e8-9d5b-c3fc7b365819', 'subtopic'::public.curated_course_node_type, 'Waste, contamination, and sustainability', 'Students learn that lab work has material consequences and that safe disposal and contamination control are part of responsible science.', 2),
  ('456eee2c-ac04-4e53-bd2e-a7ba63d2f72c', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '8c62a132-f8f0-417b-8101-92c17387fd82', 'concept'::public.curated_course_node_type, 'Chemical and biological waste streams', null, 0),
  ('e8cb7b5b-ec99-4313-a371-231fe46ff5d6', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '8c62a132-f8f0-417b-8101-92c17387fd82', 'concept'::public.curated_course_node_type, 'Cross-contamination prevention', null, 1),
  ('0d3adc24-2fd2-48a4-b2fb-f56ac7975685', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '8c62a132-f8f0-417b-8101-92c17387fd82', 'concept'::public.curated_course_node_type, 'Green chemistry and resource stewardship', null, 2),
  ('21a9c99a-b44c-46e2-9276-ad8bda356a28', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', null, 'topic'::public.curated_course_node_type, 'Experimental Design and Hypothesis Testing', 'Students move from curiosity to controlled investigation. This unit teaches them how to design experiments that can actually answer a question, not merely produce activity.', 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('7aa001cc-5339-4933-8fe6-d297704415f0', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '21a9c99a-b44c-46e2-9276-ad8bda356a28', 'subtopic'::public.curated_course_node_type, 'Variables, controls, and comparisons', 'Students learn how independent variables, dependent variables, control groups, constants, and comparison conditions shape interpretability.', 0),
