  ('a9448686-5c4d-43c8-a523-3517e9382e0c', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '21a9c99a-b44c-46e2-9276-ad8bda356a28', 'subtopic'::public.curated_course_node_type, 'Hypothesis testing in practice', 'This subtopic turns hypotheses into testable predictions and introduces the logic of rejecting, supporting, or revising explanations.', 1),
  ('0b65a94c-6c59-4abd-918d-3ee94342e1e0', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'a9448686-5c4d-43c8-a523-3517e9382e0c', 'concept'::public.curated_course_node_type, 'Null and alternative hypotheses', null, 0),
  ('4bd901bc-6484-478e-a1fc-033a12d4a10d', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'a9448686-5c4d-43c8-a523-3517e9382e0c', 'concept'::public.curated_course_node_type, 'Operational definitions', null, 1),
  ('e68d2c89-c6e9-4f03-8b6c-516d4a9ffdaf', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'a9448686-5c4d-43c8-a523-3517e9382e0c', 'concept'::public.curated_course_node_type, 'Criteria for evidence', null, 2),
  ('275e6ae6-4738-4404-a60c-e05a157839c8', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '21a9c99a-b44c-46e2-9276-ad8bda356a28', 'subtopic'::public.curated_course_node_type, 'Replication and reproducibility', 'Students learn why repeated trials, transparent protocols, and reproducible methods matter for trustworthy science.', 2),
  ('e8cbb202-7b0b-4808-b215-c335c4d97c5a', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '275e6ae6-4738-4404-a60c-e05a157839c8', 'concept'::public.curated_course_node_type, 'Technical and biological replicates', null, 0),
  ('bcbf821b-fc30-4b6d-99c1-d83a97460a89', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '275e6ae6-4738-4404-a60c-e05a157839c8', 'concept'::public.curated_course_node_type, 'Protocol clarity', null, 1),
  ('a3caccf3-103a-4a4e-8560-e69430bd129a', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '275e6ae6-4738-4404-a60c-e05a157839c8', 'concept'::public.curated_course_node_type, 'Reproducible workflows', null, 2),
  ('0cf03372-9cb9-4311-a256-52c95eda0473', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', null, 'topic'::public.curated_course_node_type, 'Data Collection, Statistics, and Visualization', 'This unit equips students to transform raw observations into interpretable evidence. They learn the basics of organizing data, summarizing variation, visualizing patterns, and making careful claims.', 4),
  ('625f6f28-649b-4762-b2b8-2b2ab4d63f55', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '0cf03372-9cb9-4311-a256-52c95eda0473', 'subtopic'::public.curated_course_node_type, 'Data tables and metadata', 'Students learn to organize lab data so another person could understand what was measured, how, when, and under what conditions.', 0),
  ('c3029ad4-712a-4a8d-816b-4fc6ec55de07', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '625f6f28-649b-4762-b2b8-2b2ab4d63f55', 'concept'::public.curated_course_node_type, 'Tidy data principles', null, 0),
