  ('03388b72-04a6-4603-afde-e8dc4cc4c092', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '625f6f28-649b-4762-b2b8-2b2ab4d63f55', 'concept'::public.curated_course_node_type, 'Lab notebook conventions', null, 2),
