  ('a5506083-e2d7-41aa-9e9d-f81fdd9b076a', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '985fe37e-0c60-4a90-bf6b-f557d84bfdf6', 'concept'::public.curated_course_node_type, 'Moles and molar mass', null, 1),
