  ('e32c0167-62aa-4097-a784-766674eadaf4', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '08201665-7fe8-4b12-b802-78fa361da1b0', 'concept'::public.curated_course_node_type, 'DNA structure and replication', null, 0),
