  ('07b4470d-1068-483a-aec2-b031b74450b8', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '0777f579-6061-487d-ba7b-65a616ccf1d7', 'subtopic'::public.curated_course_node_type, 'Evolution and natural selection', 'This subtopic explains how heritable variation, differential survival, and reproduction shape populations over time.', 1),
