  ('f6ff7690-7b9d-465b-b42d-b0f1bdbe74b3', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'b630cc9f-6ab2-499f-bf43-1ea502ea09cb', 'concept'::public.curated_course_node_type, 'Biodiversity measurement', null, 2),
