  ('7ff72550-a2b0-4361-abf0-0970a529c09b', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '10c89314-3222-453f-b308-7aaedf77d17a', 'concept'::public.curated_course_node_type, 'Carbon, nitrogen, phosphorus, and water cycles', null, 0),
  ('b75c2a8b-bd9e-48a2-9149-140c6a65e890', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '10c89314-3222-453f-b308-7aaedf77d17a', 'concept'::public.curated_course_node_type, 'Food webs', null, 1),
  ('c11feaac-a8fa-4067-bd35-f264bb415176', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '10c89314-3222-453f-b308-7aaedf77d17a', 'concept'::public.curated_course_node_type, 'Primary productivity', null, 2),
  ('035315b7-4666-4920-b9d9-4427f589186a', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '81a8fb60-490e-44ec-a7c6-933b37bcc23b', 'subtopic'::public.curated_course_node_type, 'Climate, weather, and Earth observations', 'This subtopic introduces climate drivers, weather patterns, satellite observation, and long-term environmental data.', 1),
  ('c3fc1926-c777-4de0-8666-55ba7a558bc3', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '035315b7-4666-4920-b9d9-4427f589186a', 'concept'::public.curated_course_node_type, 'Atmosphere and ocean interactions', null, 0),
