  ('4447fc54-2599-455e-beeb-2e6b6879bf9a', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '035315b7-4666-4920-b9d9-4427f589186a', 'concept'::public.curated_course_node_type, 'Remote sensing and climate records', null, 2),
  ('3d1785f2-5d8c-457a-b7a0-b867cf4bdbac', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '81a8fb60-490e-44ec-a7c6-933b37bcc23b', 'subtopic'::public.curated_course_node_type, 'Human impacts and sustainability', 'Students examine pollution, land use, resource consumption, biodiversity loss, and solutions grounded in evidence.', 2),
  ('53333cff-8574-4d33-8a52-ac18d3b502cc', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '3d1785f2-5d8c-457a-b7a0-b867cf4bdbac', 'concept'::public.curated_course_node_type, 'Pollution pathways', null, 0),
  ('e65dae4e-adc9-469c-bda0-7a5c5a064edd', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '3d1785f2-5d8c-457a-b7a0-b867cf4bdbac', 'concept'::public.curated_course_node_type, 'Resource use and waste', null, 1),
  ('a2e76b6b-49c1-4096-af3e-e777b5ea16ff', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '3d1785f2-5d8c-457a-b7a0-b867cf4bdbac', 'concept'::public.curated_course_node_type, 'Sustainability and resilience', null, 2),
  ('4d66f5c6-7cc2-49f6-906f-7eada4f8aa1a', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', null, 'topic'::public.curated_course_node_type, 'Water, Air, Soil, and Field Methods', 'Field science asks students to measure real systems outside highly controlled lab conditions. This unit introduces practical sampling, environmental monitoring, and field-data interpretation.', 12),
  ('f1ad072d-7118-4036-9b6c-aea6222274ae', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '4d66f5c6-7cc2-49f6-906f-7eada4f8aa1a', 'subtopic'::public.curated_course_node_type, 'Sampling design in the field', 'Students learn how location, timing, replication, and sampling bias shape conclusions about natural systems.', 0),
  ('84d28459-77ce-402a-b7dd-c6f02588b7b5', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'f1ad072d-7118-4036-9b6c-aea6222274ae', 'concept'::public.curated_course_node_type, 'Transects and quadrats', null, 0),
  ('7f30642c-b2ef-41d1-b566-31269df93a7e', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', 'f1ad072d-7118-4036-9b6c-aea6222274ae', 'concept'::public.curated_course_node_type, 'Random and stratified sampling', null, 1);
