  ('49d5843d-7d2e-4afe-a846-e3932dfe97df', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '2aee6750-6026-417d-ae56-e23f36b11da6', 'concept'::public.curated_course_node_type, 'Research question and rationale', null, 0),
