  ('c865c90b-f595-4b74-9a7d-2897404850a8', 'f8a9b0c1-2d3e-4f69-8c89-9a0b1c2d3e69', '1064ea22-7570-4b76-a802-70e987add980', 'concept'::public.curated_course_node_type, 'Hazard versus risk', null, 0),
