  'natural-science-with-lab',
  null,
  'Natural Science with Lab',
  'Natural Science with Lab',
  'Natural Science with Lab is an interdisciplinary first-year laboratory course that introduces students to scientific inquiry through biology, chemistry, physics, and environmental science. Students learn how to ask testable questions, measure carefully, work safely, analyze uncertainty, interpret data, use models, and communicate scientific findings. The course is designed for Liberal Arts students who need a rigorous lab-science foundation without assuming a single major track.',
  $nscljson${"slug": "natural-science-with-lab", "title": "Natural Science with Lab", "description": "Natural Science with Lab is an interdisciplinary first-year laboratory course that introduces students to scientific inquiry through biology, chemistry, physics, and environmental science. Students learn how to ask testable questions, measure carefully, work safely, analyze uncertainty, interpret data, use models, and communicate scientific findings. The course is designed for Liberal Arts students who need a rigorous lab-science foundation without assuming a single major track.", "topics": [{"id": "a8d85716-2953-4854-ae9e-3730b916231d", "type": "topic", "title": "Science as a Way of Knowing", "description": "This opening unit frames natural science as a disciplined way of asking questions about the physical, chemical, biological, and Earth systems around us. Students learn that science is not a list of facts; it is a method for building, testing, revising, and communicating explanations.", "children": [{"id": "b2a1e4c2-a850-4561-a0f8-98dd9306af9f", "type": "subtopic", "title": "Observation, inference, and explanation", "children": [{"id": "e6c4adf6-11cc-4e74-b8d2-3c25b1034145", "type": "concept", "title": "Qualitative and quantitative observations"}, {"id": "2be70b78-1b88-4d70-aae0-05a0cd472fea", "type": "concept", "title": "Inference versus assumption"}, {"id": "c0571489-96b9-4c0c-8013-462c48ab56f4", "type": "concept", "title": "Evidence-based explanation"}], "description": "Students learn to separate what is directly observed from the interpretations and models built from those observations."}, {"id": "7053c5b9-19d0-4cba-a099-354b4b1348d5", "type": "subtopic", "title": "The scientific method and scientific inquiry", "children": [{"id": "2851f60f-1fc2-4eb0-913b-506ed1f4d336", "type": "concept", "title": "Questions and hypotheses"}, {"id": "ae70a99c-abed-4e72-87be-3768859429aa", "type": "concept", "title": "Prediction and testability"}, {"id": "ca590bb5-ef1a-4ede-93e6-d183aee11a60", "type": "concept", "title": "Iteration and revision"}], "description": "This subtopic introduces the cycle of questioning, prediction, testing, analysis, and revision used across laboratory sciences."}, {"id": "7b43adc7-9606-4201-a5d1-aff00c5d6595", "type": "subtopic", "title": "Scientific literacy and source evaluation", "children": [{"id": "915edbe3-64cd-4ed3-b353-dce8f351b1dc", "type": "concept", "title": "Peer review and authority"}, {"id": "6f081c34-cb35-4ecc-9b15-38c12cce05db", "type": "concept", "title": "Correlation, causation, and overclaiming"}, {"id": "637a0913-e93c-4fda-aa63-e80a6c445380", "type": "concept", "title": "Science news and misinformation"}], "description": "Students practice reading scientific claims carefully, identifying credible sources, and recognizing uncertainty in public science communication."}]}, {"id": "f97911e6-26a4-446a-ab80-b1a7c5293822", "type": "topic", "title": "Measurement, Units, Uncertainty, and Significant Figures", "description": "Laboratory science depends on careful measurement. This unit gives students the habits needed to collect data that are meaningful, comparable, and honest about their limits.", "children": [{"id": "b03e72c0-b55d-4027-9c2d-df735d27c7ad", "type": "subtopic", "title": "Units and dimensional reasoning", "children": [{"id": "6f8c86b8-fe4f-40c0-a4b3-94639f677bae", "type": "concept", "title": "SI base and derived units"}, {"id": "ab09423b-3387-4583-ac32-b1466b61ba61", "type": "concept", "title": "Unit conversion and dimensional checks"}, {"id": "54900379-2db3-4f2d-931a-81a24f99db15", "type": "concept", "title": "Orders of magnitude and scale"}], "description": "Students learn to use SI units, unit conversions, dimensional analysis, and scale reasoning as basic tools for scientific problem solving."}, {"id": "cd31ca29-d5f9-4fcc-b4eb-de91131dd6c0", "type": "subtopic", "title": "Accuracy, precision, and uncertainty", "children": [{"id": "01e87790-8ba5-4fe2-8c54-779e47c849a1", "type": "concept", "title": "Systematic and random error"}, {"id": "9af4e36f-0422-4c8b-bda1-60c3d0ddbf81", "type": "concept", "title": "Instrument resolution"}, {"id": "f940aaf5-9227-40a9-8c92-c1d722f91171", "type": "concept", "title": "Uncertainty intervals"}], "description": "This subtopic teaches students to distinguish closeness to the true value from repeatability, and to communicate uncertainty appropriately."}, {"id": "ec597121-a78c-48c6-a3f9-3b6674082a19", "type": "subtopic", "title": "Significant figures and scientific notation", "children": [{"id": "d9c72aa8-9c13-4e78-add7-306e23ec6de9", "type": "concept", "title": "Rounding rules"}, {"id": "c5724b93-17d4-466e-97fe-ab316dce0deb", "type": "concept", "title": "Propagation in simple calculations"}, {"id": "3a6d6230-75b2-4fd1-a7aa-00e1a006799f", "type": "concept", "title": "Scientific notation in lab records"}], "description": "Students learn how reported numbers carry information about measurement quality and how to avoid false precision."}]}, {"id": "59eb633b-17b2-41e8-9d5b-c3fc7b365819", "type": "topic", "title": "Laboratory Safety, Ethics, and Scientific Responsibility", "description": "This lab course treats safety and ethics as core scientific skills. Students learn how to protect themselves, classmates, organisms, communities, and the integrity of the evidence they produce.", "children": [{"id": "9218b0f5-c2e6-4fe9-9107-6ed813a08016", "type": "subtopic", "title": "Safety culture and hazard recognition", "children": [{"id": "5fa4ce3d-1994-4ec4-b080-c8569edc0edf", "type": "concept", "title": "Safety Data Sheets"}, {"id": "8aad9f44-0774-4bcf-9ca8-9d161a2b9bf4", "type": "concept", "title": "PPE and engineering controls"}, {"id": "17683a89-7019-4e3f-a6e0-e28bcfeed473", "type": "concept", "title": "Emergency response basics"}], "description": "Students learn to identify physical, chemical, biological, and environmental hazards before beginning any experiment."}, {"id": "ffc27d55-9877-4f2f-a532-36ee6a11f004", "type": "subtopic", "title": "Ethical conduct in the laboratory", "children": [{"id": "3256e356-9838-4e64-97af-c557fc1ea0cd", "type": "concept", "title": "Data integrity"}, {"id": "9ba1d008-06e5-4b7f-ae6c-3f1d4e9dc38f", "type": "concept", "title": "Authorship and collaboration"}, {"id": "e322cf40-ac6e-4a6f-aa0a-a66702593ef7", "type": "concept", "title": "Animal, human, and environmental considerations"}], "description": "This subtopic introduces honesty in data recording, responsible collaboration, respect for living systems, and appropriate handling of uncertainty."}, {"id": "8c62a132-f8f0-417b-8101-92c17387fd82", "type": "subtopic", "title": "Waste, contamination, and sustainability", "children": [{"id": "456eee2c-ac04-4e53-bd2e-a7ba63d2f72c", "type": "concept", "title": "Chemical and biological waste streams"}, {"id": "e8cb7b5b-ec99-4313-a371-231fe46ff5d6", "type": "concept", "title": "Cross-contamination prevention"}, {"id": "0d3adc24-2fd2-48a4-b2fb-f56ac7975685", "type": "concept", "title": "Green chemistry and resource stewardship"}], "description": "Students learn that lab work has material consequences and that safe disposal and contamination control are part of responsible science."}]}, {"id": "21a9c99a-b44c-46e2-9276-ad8bda356a28", "type": "topic", "title": "Experimental Design and Hypothesis Testing", "description": "Students move from curiosity to controlled investigation. This unit teaches them how to design experiments that can actually answer a question, not merely produce activity.", "children": [{"id": "7aa001cc-5339-4933-8fe6-d297704415f0", "type": "subtopic", "title": "Variables, controls, and comparisons", "children": [{"id": "24d9b532-c158-454e-acc7-e2faf3ea0b1e", "type": "concept", "title": "Independent and dependent variables"}, {"id": "2ca22a37-1998-4135-aa45-165d13b20404", "type": "concept", "title": "Positive and negative controls"}, {"id": "1b4a0f4b-f98b-46d9-a46f-78698fea0438", "type": "concept", "title": "Confounding variables"}], "description": "Students learn how independent variables, dependent variables, control groups, constants, and comparison conditions shape interpretability."}, {"id": "a9448686-5c4d-43c8-a523-3517e9382e0c", "type": "subtopic", "title": "Hypothesis testing in practice", "children": [{"id": "0b65a94c-6c59-4abd-918d-3ee94342e1e0", "type": "concept", "title": "Null and alternative hypotheses"}, {"id": "4bd901bc-6484-478e-a1fc-033a12d4a10d", "type": "concept", "title": "Operational definitions"}, {"id": "e68d2c89-c6e9-4f03-8b6c-516d4a9ffdaf", "type": "concept", "title": "Criteria for evidence"}], "description": "This subtopic turns hypotheses into testable predictions and introduces the logic of rejecting, supporting, or revising explanations."}, {"id": "275e6ae6-4738-4404-a60c-e05a157839c8", "type": "subtopic", "title": "Replication and reproducibility", "children": [{"id": "e8cbb202-7b0b-4808-b215-c335c4d97c5a", "type": "concept", "title": "Technical and biological replicates"}, {"id": "bcbf821b-fc30-4b6d-99c1-d83a97460a89", "type": "concept", "title": "Protocol clarity"}, {"id": "a3caccf3-103a-4a4e-8560-e69430bd129a", "type": "concept", "title": "Reproducible workflows"}], "description": "Students learn why repeated trials, transparent protocols, and reproducible methods matter for trustworthy science."}]}, {"id": "0cf03372-9cb9-4311-a256-52c95eda0473", "type": "topic", "title": "Data Collection, Statistics, and Visualization", "description": "This unit equips students to transform raw observations into interpretable evidence. They learn the basics of organizing data, summarizing variation, visualizing patterns, and making careful claims.", "children": [{"id": "625f6f28-649b-4762-b2b8-2b2ab4d63f55", "type": "subtopic", "title": "Data tables and metadata", "children": [{"id": "c3029ad4-712a-4a8d-816b-4fc6ec55de07", "type": "concept", "title": "Tidy data principles"}, {"id": "5f6bb10e-8ec0-417e-86a0-b11cab6b6ad9", "type": "concept", "title": "Metadata and labels"}, {"id": "03388b72-04a6-4603-afde-e8dc4cc4c092", "type": "concept", "title": "Lab notebook conventions"}], "description": "Students learn to organize lab data so another person could understand what was measured, how, when, and under what conditions."}, {"id": "3dab4d23-3d37-46fc-927f-f723ef62b417", "type": "subtopic", "title": "Descriptive statistics and error bars", "children": [{"id": "1c6e7328-848c-4bbc-8410-ef5e7182232f", "type": "concept", "title": "Central tendency"}, {"id": "45135314-3dd8-462a-8794-c97d53d88105", "type": "concept", "title": "Variation and spread"}, {"id": "07300e79-ac8f-4773-ae67-b0cc664889db", "type": "concept", "title": "Uncertainty visualization"}], "description": "This subtopic introduces means, medians, ranges, standard deviation, standard error, and confidence intervals at an introductory level."}, {"id": "7c50af6b-6b5f-4b21-a2fb-036e698a5e46", "type": "subtopic", "title": "Graphs and scientific storytelling", "children": [{"id": "907626b9-fd9f-4975-b337-ed268528ecc8", "type": "concept", "title": "Scatterplots and line graphs"}, {"id": "20b2b068-7987-4e4c-868c-33a1aa096c31", "type": "concept", "title": "Bar charts and boxplots"}, {"id": "b0061995-aed5-4d68-b223-961ca9a3f0ef", "type": "concept", "title": "Axis labels, captions, and visual integrity"}], "description": "Students practice choosing the right visual form and avoiding misleading charts."}]}, {"id": "cf24eebf-7ab0-4364-9b04-25c4a46a6616", "type": "topic", "title": "Matter, Atoms, Molecules, and Chemical Change", "description": "Chemistry provides the language of matter and transformation. This unit gives students enough chemical foundation to understand substances, reactions, solutions, and laboratory analysis.", "children": [{"id": "e0bb7d01-970b-419a-97fc-d2dcc8c8afed", "type": "subtopic", "title": "Atomic structure and periodic patterns", "children": [{"id": "85b90c99-8239-44ce-b041-79f4b61c3ca2", "type": "concept", "title": "Protons, neutrons, and electrons"}, {"id": "2e758182-7e8c-418e-b35b-026a02a60519", "type": "concept", "title": "Electron configuration"}, {"id": "e56425fc-d7f7-4073-bec5-7dec844c00b8", "type": "concept", "title": "Periodic trends"}], "description": "Students connect atomic structure to periodic trends and the behavior of elements."}, {"id": "8eb2e90c-ed83-4d75-9747-604e4ef535f4", "type": "subtopic", "title": "Bonding, molecules, and intermolecular forces", "children": [{"id": "7d8482df-2494-4490-9170-2aa9197e4e1c", "type": "concept", "title": "Ionic and covalent bonding"}, {"id": "edbcccec-9492-4fdf-b123-422ef5de6541", "type": "concept", "title": "Molecular geometry"}, {"id": "b26840c1-39b3-487f-b920-f1042b213056", "type": "concept", "title": "Polarity and intermolecular forces"}], "description": "This subtopic explains how atoms combine and why molecular structure influences properties."}, {"id": "985fe37e-0c60-4a90-bf6b-f557d84bfdf6", "type": "subtopic", "title": "Chemical reactions and stoichiometry", "children": [{"id": "5f90e26b-0ef9-44e5-8878-6f37c26f88c0", "type": "concept", "title": "Balanced equations"}, {"id": "a5506083-e2d7-41aa-9e9d-f81fdd9b076a", "type": "concept", "title": "Moles and molar mass"}, {"id": "0447dd1b-15cd-4832-8a5d-5896c97b04b8", "type": "concept", "title": "Limiting reactants and yield"}], "description": "Students learn to represent reactions, balance equations, and reason quantitatively about reactants and products."}]}, {"id": "8d8042b1-8bf6-4530-9546-cfe790115700", "type": "topic", "title": "Energy, Thermodynamics, and Transformations", "description": "Energy links physics, chemistry, biology, and Earth systems. This unit helps students track how energy is stored, transferred, degraded, and conserved across natural processes.", "children": [{"id": "699efd77-d965-4cb9-978b-165b1a5d8b25", "type": "subtopic", "title": "Forms of energy and conservation", "children": [{"id": "41d69e2b-9489-443b-9973-a6b912b1038d", "type": "concept", "title": "Conservation of energy"}, {"id": "deacb950-8923-4597-9bc3-abf1704d6967", "type": "concept", "title": "Energy transfer and transformation"}, {"id": "489157c9-595f-4246-9712-a69d0b22ed1e", "type": "concept", "title": "System boundaries"}], "description": "Students learn to identify kinetic, potential, thermal, chemical, electrical, and radiant energy in systems."}, {"id": "ba29917a-3818-4742-b540-ac68d075e0d0", "type": "subtopic", "title": "Heat, temperature, and thermodynamics", "children": [{"id": "5d1714c6-7194-4942-9cfd-5b62c2de2049", "type": "concept", "title": "Temperature versus heat"}, {"id": "f895cb3e-5441-4992-af4b-ecac2e3f77f8", "type": "concept", "title": "Calorimetry"}, {"id": "1a685779-1cd2-404c-b66f-60752a6563ee", "type": "concept", "title": "Entropy and spontaneity"}], "description": "This subtopic introduces temperature, heat flow, specific heat, phase changes, and entropy as practical lab ideas."}, {"id": "8d786368-a16f-49f0-9f34-805c93275888", "type": "subtopic", "title": "Energy in living and environmental systems", "children": [{"id": "dd1d0b85-0aec-4eb9-bb36-16343f1104bf", "type": "concept", "title": "Cellular respiration and photosynthesis"}, {"id": "cf983d7c-c9c9-4e09-9adc-607e20aaeb5e", "type": "concept", "title": "Food webs and trophic efficiency"}, {"id": "df389f16-8313-4881-a113-1b65ca8669c3", "type": "concept", "title": "Radiation balance and greenhouse effect"}], "description": "Students connect thermodynamic principles to metabolism, photosynthesis, ecosystems, and climate."}]}, {"id": "1137fc08-a609-4261-bd95-372115634a7e", "type": "topic", "title": "Forces, Motion, Waves, and Physical Systems", "description": "Physics gives students tools for analyzing motion, force, energy, waves, and interactions. This unit emphasizes measurable relationships and model-based reasoning.", "children": [{"id": "958f0ad5-4292-4168-b430-56a223ec1da1", "type": "subtopic", "title": "Motion and force models", "children": [{"id": "9bcc0288-21b5-4d53-a1e4-da6811007226", "type": "concept", "title": "Position, velocity, and acceleration"}, {"id": "9ad0261b-466d-48a0-b6b9-5b69dbe84b10", "type": "concept", "title": "Free-body diagrams"}, {"id": "e93de870-c456-4859-9f1a-579b368e8a87", "type": "concept", "title": "Newton's laws"}], "description": "Students use graphs, vectors, and Newton's laws to describe and explain motion."}, {"id": "79ea8b03-a943-4edf-87c3-7e00f698605a", "type": "subtopic", "title": "Work, energy, and momentum", "children": [{"id": "481a1690-d2ca-4850-a679-023eac033706", "type": "concept", "title": "Work and kinetic energy"}, {"id": "3b3fd180-b971-4828-8dfa-ee761ccf5bc5", "type": "concept", "title": "Potential energy"}, {"id": "5bf264cc-5029-4e7e-a98c-8261574cc96f", "type": "concept", "title": "Momentum and impulse"}], "description": "This subtopic connects physical interactions with conservation principles and measurable system changes."}, {"id": "a46320fd-3fa8-4609-aaef-1930dfaf0cca", "type": "subtopic", "title": "Waves and oscillations", "children": [{"id": "5dacd4e3-4182-456f-ae7a-2f159442e238", "type": "concept", "title": "Frequency, wavelength, and amplitude"}, {"id": "99eea32f-f2ae-4136-8133-806ebdd93380", "type": "concept", "title": "Interference and resonance"}, {"id": "fcfb773c-db25-4eee-a07a-df623fee3b95", "type": "concept", "title": "Sound and light as waves"}], "description": "Students study wave properties that connect sound, light, water waves, seismic motion, and instrumentation."}]}, {"id": "d66e2807-7466-4021-94b9-dbf42a4b872b", "type": "topic", "title": "Electricity, Magnetism, Light, and Instrumentation", "description": "Modern lab science depends on instruments that convert physical interactions into measurable signals. This unit introduces basic electricity, magnetism, optics, and sensors.", "children": [{"id": "ef4cd5f6-3b70-439b-9185-d7941ac78d60", "type": "subtopic", "title": "Electric circuits and measurement", "children": [{"id": "e2f4e20c-2cac-483b-98f1-d110967e7f8b", "type": "concept", "title": "Ohm's law"}, {"id": "033bf22c-1f0a-45b3-8bc3-f84da9207aa8", "type": "concept", "title": "Series and parallel circuits"}, {"id": "7e611b52-b1a2-47c9-aeac-d91cfc954277", "type": "concept", "title": "Multimeters and sensors"}], "description": "Students learn how voltage, current, resistance, and simple circuits support measurement and instrumentation."}, {"id": "d5e1d034-bab7-4736-8622-6a4a9d4fd6dc", "type": "subtopic", "title": "Magnetism and electromagnetic induction", "children": [{"id": "a534ff69-a511-411a-8fa2-702ba297adee", "type": "concept", "title": "Magnetic fields"}, {"id": "7a4d3d4a-2018-44b2-9194-579eae1562a5", "type": "concept", "title": "Electromagnetic induction"}, {"id": "13d217c5-4dbc-4362-bf47-f515019e5c08", "type": "concept", "title": "Motors and generators"}], "description": "This subtopic introduces the relationships among currents, fields, induction, generators, and common instruments."}, {"id": "672dcb3b-2ff6-45d4-b541-0c2756249087", "type": "subtopic", "title": "Light, optics, and spectroscopy", "children": [{"id": "8e34154d-feac-4829-aecf-e4fbf71d8ed8", "type": "concept", "title": "Reflection and refraction"}, {"id": "4e4cbd39-cad1-4b76-a6ff-d8c7eb612c13", "type": "concept", "title": "Lenses and image formation"}, {"id": "34002e83-8335-4b24-840e-12fc08507cc4", "type": "concept", "title": "Absorption and emission spectra"}], "description": "Students connect light behavior to microscopy, cameras, colorimetry, spectrophotometry, and remote sensing."}]}, {"id": "bfea3b82-3ef7-4811-86f0-70bc24a14a7c", "type": "topic", "title": "Cells, Biomolecules, and Microscopy", "description": "Biology begins with the cell as the basic unit of life. This unit links molecular structure, cellular organization, microscopy, and experimental observation.", "children": [{"id": "d906507e-2c88-4afd-b97a-9a7ce5d71978", "type": "subtopic", "title": "Biomolecules and water", "children": [{"id": "1029ed90-3d70-458a-8da4-d1926128296e", "type": "concept", "title": "Water properties"}, {"id": "432eeab5-94d2-4af0-849a-dd2abafb58f2", "type": "concept", "title": "Macromolecule structure and function"}, {"id": "2033ca73-b867-4b23-8a46-a8e3231439e1", "type": "concept", "title": "Enzymes and catalysis"}], "description": "Students learn how carbohydrates, lipids, proteins, nucleic acids, and water support life processes."}, {"id": "1dd45f41-4b7d-40bf-b3f6-02d784d42381", "type": "subtopic", "title": "Cell structure and function", "children": [{"id": "39d5acf3-ca08-4802-8ec4-1f87824ceacd", "type": "concept", "title": "Prokaryotic and eukaryotic cells"}, {"id": "d787e0c5-3eab-4a86-96ff-83826b392fbf", "type": "concept", "title": "Membranes and transport"}, {"id": "08b68e9f-ec58-4df6-a619-e6d39ea10fef", "type": "concept", "title": "Organelles and compartmentalization"}], "description": "This subtopic introduces membranes, organelles, cell specialization, and transport."}, {"id": "6c96a8a4-3dc0-4b83-ae57-86124315beb6", "type": "subtopic", "title": "Microscopy and biological observation", "children": [{"id": "ac4832bf-813d-4d52-932c-b2eee7197ed4", "type": "concept", "title": "Light microscopy"}, {"id": "b95ecc32-bf41-41c7-8987-2f146edbd1db", "type": "concept", "title": "Magnification and resolution"}, {"id": "738c12c9-b1cc-44c2-9b41-93d54600f7f8", "type": "concept", "title": "Staining and specimen preparation"}], "description": "Students learn to prepare specimens, use microscopes responsibly, and connect image evidence to biological claims."}]}, {"id": "0777f579-6061-487d-ba7b-65a616ccf1d7", "type": "topic", "title": "Genetics, Evolution, and Biodiversity", "description": "This unit connects inheritance, variation, natural selection, and the diversity of life. Students learn how biological patterns emerge across generations and ecosystems.", "children": [{"id": "08201665-7fe8-4b12-b802-78fa361da1b0", "type": "subtopic", "title": "DNA, genes, and inheritance", "children": [{"id": "e32c0167-62aa-4097-a784-766674eadaf4", "type": "concept", "title": "DNA structure and replication"}, {"id": "40e981cc-e674-4157-b640-5dcbf7a9e32f", "type": "concept", "title": "Transcription and translation"}, {"id": "41083dd9-8947-4bbe-8d8c-f73f1ae3f185", "type": "concept", "title": "Mendelian inheritance"}], "description": "Students learn the basic flow of genetic information and how traits are transmitted and expressed."}, {"id": "07b4470d-1068-483a-aec2-b031b74450b8", "type": "subtopic", "title": "Evolution and natural selection", "children": [{"id": "f178f412-a668-471f-94c7-955f5ab675e2", "type": "concept", "title": "Variation and fitness"}, {"id": "a5fcaf49-676e-4d36-afd3-615f8daeb2a2", "type": "concept", "title": "Natural selection"}, {"id": "963669d7-56d9-4b21-977e-14871996fa7b", "type": "concept", "title": "Speciation and phylogeny"}], "description": "This subtopic explains how heritable variation, differential survival, and reproduction shape populations over time."}, {"id": "b630cc9f-6ab2-499f-bf43-1ea502ea09cb", "type": "subtopic", "title": "Biodiversity and classification", "children": [{"id": "d99a5ee3-6e36-47db-b4f3-fbc0ebb82edd", "type": "concept", "title": "Domains and kingdoms"}, {"id": "b840a2af-896a-463c-9505-14eae1dd85f5", "type": "concept", "title": "Phylogenetic trees"}, {"id": "f6ff7690-7b9d-465b-b42d-b0f1bdbe74b3", "type": "concept", "title": "Biodiversity measurement"}], "description": "Students learn why biodiversity matters scientifically and practically, and how organisms are classified."}]}, {"id": "81a8fb60-490e-44ec-a7c6-933b37bcc23b", "type": "topic", "title": "Ecology, Earth Systems, and Environmental Change", "description": "Natural science is strongest when students can connect organisms, matter, energy, Earth processes, and human impacts. This unit integrates ecology and environmental science.", "children": [{"id": "10c89314-3222-453f-b308-7aaedf77d17a", "type": "subtopic", "title": "Ecosystems and biogeochemical cycles", "children": [{"id": "7ff72550-a2b0-4361-abf0-0970a529c09b", "type": "concept", "title": "Carbon, nitrogen, phosphorus, and water cycles"}, {"id": "b75c2a8b-bd9e-48a2-9149-140c6a65e890", "type": "concept", "title": "Food webs"}, {"id": "c11feaac-a8fa-4067-bd35-f264bb415176", "type": "concept", "title": "Primary productivity"}], "description": "Students learn how matter and energy move through ecosystems and Earth systems."}, {"id": "035315b7-4666-4920-b9d9-4427f589186a", "type": "subtopic", "title": "Climate, weather, and Earth observations", "children": [{"id": "c3fc1926-c777-4de0-8666-55ba7a558bc3", "type": "concept", "title": "Atmosphere and ocean interactions"}, {"id": "019cdc42-052e-462d-94ce-5c83c05b8c05", "type": "concept", "title": "Climate versus weather"}, {"id": "4447fc54-2599-455e-beeb-2e6b6879bf9a", "type": "concept", "title": "Remote sensing and climate records"}], "description": "This subtopic introduces climate drivers, weather patterns, satellite observation, and long-term environmental data."}, {"id": "3d1785f2-5d8c-457a-b7a0-b867cf4bdbac", "type": "subtopic", "title": "Human impacts and sustainability", "children": [{"id": "53333cff-8574-4d33-8a52-ac18d3b502cc", "type": "concept", "title": "Pollution pathways"}, {"id": "e65dae4e-adc9-469c-bda0-7a5c5a064edd", "type": "concept", "title": "Resource use and waste"}, {"id": "a2e76b6b-49c1-4096-af3e-e777b5ea16ff", "type": "concept", "title": "Sustainability and resilience"}], "description": "Students examine pollution, land use, resource consumption, biodiversity loss, and solutions grounded in evidence."}]}, {"id": "4d66f5c6-7cc2-49f6-906f-7eada4f8aa1a", "type": "topic", "title": "Water, Air, Soil, and Field Methods", "description": "Field science asks students to measure real systems outside highly controlled lab conditions. This unit introduces practical sampling, environmental monitoring, and field-data interpretation.", "children": [{"id": "f1ad072d-7118-4036-9b6c-aea6222274ae", "type": "subtopic", "title": "Sampling design in the field", "children": [{"id": "84d28459-77ce-402a-b7dd-c6f02588b7b5", "type": "concept", "title": "Transects and quadrats"}, {"id": "7f30642c-b2ef-41d1-b566-31269df93a7e", "type": "concept", "title": "Random and stratified sampling"}, {"id": "50b4489c-1ee6-493f-86d8-177eaf2e5c05", "type": "concept", "title": "Spatial and temporal variation"}], "description": "Students learn how location, timing, replication, and sampling bias shape conclusions about natural systems."}, {"id": "ae5edcf6-69b6-4c79-8803-4c7e1cfa30f4", "type": "subtopic", "title": "Water and soil measurements", "children": [{"id": "216e59d6-8994-49d3-bd89-756d9eb4ce70", "type": "concept", "title": "pH, conductivity, and dissolved oxygen"}, {"id": "5f4f062f-5f99-4bc7-908f-2c7f3b0b5946", "type": "concept", "title": "Turbidity and nutrients"}, {"id": "2f048337-7c38-40c1-a428-c1792e800ff0", "type": "concept", "title": "Soil texture and moisture"}], "description": "This subtopic introduces common field and bench measurements used in environmental science."}, {"id": "e3b0b127-e3ed-4c24-adf0-8bad618f795f", "type": "subtopic", "title": "Air, weather, and microclimate data", "children": [{"id": "037929db-8095-4498-a89e-90c41efe6178", "type": "concept", "title": "Temperature, humidity, and pressure"}, {"id": "90c1f0ca-1be7-4443-af2e-e09c6e310bc9", "type": "concept", "title": "Wind and precipitation"}, {"id": "08d82b6e-a98c-4700-8cb5-91f20b389337", "type": "concept", "title": "Particulates and air quality indicators"}], "description": "Students connect local atmospheric measurements to larger environmental processes."}]}, {"id": "7ba3eb3a-f68f-4c76-8afb-2ca37a2eb882", "type": "topic", "title": "Core Laboratory Techniques Across the Sciences", "description": "Students need a practical toolkit that transfers across biology, chemistry, physics, and environmental laboratories. This unit focuses on technique, calibration, and disciplined execution.", "children": [{"id": "8f0205e5-7e0d-4e2c-97e7-58bcd1e31f39", "type": "subtopic", "title": "Mass, volume, and solution preparation", "children": [{"id": "04eee5c3-173c-4239-82ca-b1a89d1c0949", "type": "concept", "title": "Balances and weighing"}, {"id": "d638c13a-c79c-4b6d-9d43-fdb0e6c7b460", "type": "concept", "title": "Pipettes and volumetric glassware"}, {"id": "1e1c9e1f-43b3-457f-898d-52459fc9063a", "type": "concept", "title": "Molarity and dilution"}], "description": "Students learn the basic manipulations behind reliable chemical and biological lab work."}, {"id": "f0cedf9b-774a-4508-8065-b6b943a159a3", "type": "subtopic", "title": "Separation and identification methods", "children": [{"id": "6bf893a3-1986-4460-8ce1-d042a255ca11", "type": "concept", "title": "Filtration and centrifugation"}, {"id": "71a721ed-17d9-4351-a4d6-178fc01be8d5", "type": "concept", "title": "Chromatography"}, {"id": "93a37594-d83e-4fc9-9621-3d73b06c4a02", "type": "concept", "title": "Spectrophotometry"}], "description": "This subtopic introduces common methods for separating, identifying, or quantifying components of mixtures."}, {"id": "cd779174-74a9-4383-a8cc-1548ad96e987", "type": "subtopic", "title": "Calibration and quality control", "children": [{"id": "6cd0d211-ccd6-4440-8065-345861b31061", "type": "concept", "title": "Calibration curves"}, {"id": "c89ca6d0-2ae8-4d4c-9f7b-7970ff503502", "type": "concept", "title": "Blanks and standards"}, {"id": "ca53a560-8c23-450c-93d3-34e47cf46a8a", "type": "concept", "title": "Quality control samples"}], "description": "Students learn that instruments and methods must be checked against standards before data can be trusted."}]}, {"id": "4ae9ac8b-3262-40b9-b2eb-31c1eb76f4c9", "type": "topic", "title": "Models, Simulations, and Computational Thinking", "description": "Models help scientists reason about systems too small, large, fast, slow, dangerous, or complex to observe directly. This unit introduces conceptual, mathematical, physical, and computational models.", "children": [{"id": "42209c17-431a-4db0-b375-8abc4182e7cd", "type": "subtopic", "title": "Conceptual and mathematical models", "children": [{"id": "540a772d-5cc6-491a-9bcb-db8065cc8df6", "type": "concept", "title": "Assumptions and simplifications"}, {"id": "20b71005-18fc-4a7e-a895-9042c88fdf42", "type": "concept", "title": "Variables and parameters"}, {"id": "ff9b4500-8cdf-4e4a-8be7-4ad0e622da8b", "type": "concept", "title": "Model validation"}], "description": "Students learn how models simplify reality while preserving relationships useful for prediction and explanation."}, {"id": "94fca541-ea69-48fb-a19c-354daf7c420a", "type": "subtopic", "title": "Interactive simulations", "children": [{"id": "dfd24be1-43a8-472a-b7e7-3f926eeb5b28", "type": "concept", "title": "Parameter exploration"}, {"id": "8790039d-0d28-46a4-8bff-f602897de3a5", "type": "concept", "title": "Virtual experiments"}, {"id": "053e440d-39d4-4ea7-95c5-3148f2f9ab1f", "type": "concept", "title": "Model limitations"}], "description": "This subtopic uses simulation tools to explore systems such as circuits, molecules, populations, climate, and waves."}, {"id": "63f9c333-3edd-4dfb-9769-8a7b866ab445", "type": "subtopic", "title": "Computational data habits", "children": [{"id": "1dc89d55-35f7-4543-aa8f-7a1577d65a65", "type": "concept", "title": "Formulas and data cleaning"}, {"id": "be74203c-d5b2-4d49-839d-d4918e22dd86", "type": "concept", "title": "Versioned files"}, {"id": "c237eac8-dbc2-4768-9edc-93c0ac847298", "type": "concept", "title": "Reproducible plots"}], "description": "Students build basic comfort with spreadsheets or notebooks for calculation, plotting, and reproducible analysis."}]}, {"id": "eed35d3c-6b45-4fbb-a96b-08cf4c3ae777", "type": "topic", "title": "Scientific Communication and Lab Reports", "description": "Science becomes useful when methods, evidence, uncertainty, and conclusions are communicated clearly. This unit teaches students to write and present like beginning scientists.", "children": [{"id": "2aee6750-6026-417d-ae56-e23f36b11da6", "type": "subtopic", "title": "Lab report structure", "children": [{"id": "49d5843d-7d2e-4afe-a846-e3932dfe97df", "type": "concept", "title": "Research question and rationale"}, {"id": "e50ed541-79cd-49e7-915a-733128d07a51", "type": "concept", "title": "Methods detail and reproducibility"}, {"id": "6cf2b9f6-acf8-49ee-bbaa-746a5e804260", "type": "concept", "title": "Results versus interpretation"}], "description": "Students learn the purpose of each section: abstract, introduction, methods, results, discussion, conclusion, and references."}, {"id": "146512c2-af7e-40d5-8f83-097f32bbf292", "type": "subtopic", "title": "Figures, tables, and captions", "children": [{"id": "68d987d2-da6e-4345-a875-2cdb6c3ce84b", "type": "concept", "title": "Figure captions"}, {"id": "f53e46c0-1aae-4e6b-b0d5-764a6a875e74", "type": "concept", "title": "Table design"}, {"id": "d939fffc-5039-4996-90ee-b991535201ee", "type": "concept", "title": "Error bars and notes"}], "description": "This subtopic teaches students to present data so readers can understand the claim without guessing."}, {"id": "cfce8a83-dad3-4363-94a1-438c47236206", "type": "subtopic", "title": "Argument, citation, and revision", "children": [{"id": "284d2660-20f9-458c-ba20-f3e892baebbc", "type": "concept", "title": "Claim-evidence-reasoning"}, {"id": "a0e010f0-b0b3-4cae-ac54-fd681cba594d", "type": "concept", "title": "Citation basics"}, {"id": "3e9140e6-4687-40c3-8250-11320d0d6737", "type": "concept", "title": "Peer review and revision"}], "description": "Students learn to support conclusions with evidence, cite sources, and improve work through feedback."}]}, {"id": "f262dd9c-78fa-47d0-979a-1286a9c9a110", "type": "topic", "title": "Science, Society, Risk, and Decision-Making", "description": "Natural science informs real decisions about health, technology, climate, energy, food, water, and safety. This unit helps students connect evidence to public choices without oversimplifying uncertainty.", "children": [{"id": "1064ea22-7570-4b76-a802-70e987add980", "type": "subtopic", "title": "Risk, probability, and uncertainty", "children": [{"id": "c865c90b-f595-4b74-9a7d-2897404850a8", "type": "concept", "title": "Hazard versus risk"}, {"id": "1b8f9991-3340-4481-aa6d-4f8feb18c95a", "type": "concept", "title": "Dose-response thinking"}, {"id": "ed940695-7d02-49f7-9270-f27dc27a0c96", "type": "concept", "title": "Precaution and tradeoffs"}], "description": "Students learn how scientists and decision-makers reason about likelihood, consequence, exposure, and uncertainty."}, {"id": "08c9c507-aef6-4d4c-8a31-bebbe991f390", "type": "subtopic", "title": "Science policy and public trust", "children": [{"id": "cfbe2a35-2c5b-4cc4-aa1c-0bacc4a7802a", "type": "concept", "title": "Regulation and standards"}, {"id": "20120dd0-4988-4e2c-801a-d7b2efb7bac7", "type": "concept", "title": "Expertise and public communication"}, {"id": "66f24063-4f10-4432-9357-6aa40071ae45", "type": "concept", "title": "Conflicts of interest"}], "description": "This subtopic examines how scientific evidence moves through agencies, media, communities, and policy debates."}, {"id": "ec22c161-7b64-416f-830f-391e2a4a5a75", "type": "subtopic", "title": "Current scientific issues", "children": [{"id": "af5d6f4e-472c-4cb2-883f-c0ef0408d113", "type": "concept", "title": "Climate and energy transitions"}, {"id": "31e1e547-4f3f-427c-ba0b-f86f20c92eb0", "type": "concept", "title": "Water quality and public health"}, {"id": "1b2106ff-52c0-485e-b5c4-8ee830b3b108", "type": "concept", "title": "Biotechnology and emerging technologies"}], "description": "Students apply course tools to contemporary issues where biology, chemistry, physics, and environmental science intersect."}]}, {"id": "f89380f1-a2b4-4515-94f0-ea7d5348b7d1", "type": "topic", "title": "Integrated Capstone Lab Investigation", "description": "The course culminates in an investigation where students ask a question, design a method, collect data, analyze uncertainty, and communicate results. The goal is to practice science as a complete workflow.", "children": [{"id": "e84671c0-7882-4035-8012-735c17633ba7", "type": "subtopic", "title": "Question, background, and design proposal", "children": [{"id": "e4b8c070-4a91-47da-a42d-2a0c63e0ea40", "type": "concept", "title": "Researchable question"}, {"id": "5c1b973b-d3eb-4f94-b82e-73a43aa9199a", "type": "concept", "title": "Background source map"}, {"id": "e9b234c1-da83-4445-8fed-251789311b38", "type": "concept", "title": "Variables, controls, and safety plan"}], "description": "Students formulate a focused question, review relevant concepts, and propose a safe, feasible investigation."}, {"id": "ee73a0b1-5c86-4108-bba8-4b91cd381699", "type": "subtopic", "title": "Data collection and analysis", "children": [{"id": "6d5504e3-d668-45f1-bd7c-e21b65a30dd9", "type": "concept", "title": "Protocol execution"}, {"id": "5e523657-f97b-4ec2-ba5b-77e93e377199", "type": "concept", "title": "Data cleaning and analysis"}, {"id": "5011f611-edc3-4ed2-b18d-ef8b5a72f306", "type": "concept", "title": "Uncertainty and error evaluation"}], "description": "This subtopic guides students through careful measurement, troubleshooting, statistical summary, and visualization."}, {"id": "b87787ce-6b54-44ff-aa7a-b8d5e98c4efd", "type": "subtopic", "title": "Poster, report, and reflection", "children": [{"id": "458b7284-4f0f-4332-b578-1e59c72e2c08", "type": "concept", "title": "Scientific poster or report"}, {"id": "a356d862-c76d-48b0-abf0-68a60ae17888", "type": "concept", "title": "Oral explanation"}, {"id": "a3af85f9-cec5-4afb-922a-f580e31b680b", "type": "concept", "title": "Limitations and next steps"}], "description": "Students present the investigation in a lab report or poster and reflect on limitations, ethics, and future work."}]}], "dbBacked": true}$nscljson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'natural-science-with-lab'
);

update public.learning_paths
set
  title = 'Natural Science with Lab',
  goal = 'Natural Science with Lab',
  summary = 'Natural Science with Lab is an interdisciplinary first-year laboratory course that introduces students to scientific inquiry through biology, chemistry, physics, and environmental science. Students learn how to ask testable questions, measure carefully, work safely, analyze uncertainty, interpret data, use models, and communicate scientific findings. The course is designed for Liberal Arts students who need a rigorous lab-science foundation without assuming a single major track.',
  data = $nscljson${"slug": "natural-science-with-lab", "title": "Natural Science with Lab", "description": "Natural Science with Lab is an interdisciplinary first-year laboratory course that introduces students to scientific inquiry through biology, chemistry, physics, and environmental science. Students learn how to ask testable questions, measure carefully, work safely, analyze uncertainty, interpret data, use models, and communicate scientific findings. The course is designed for Liberal Arts students who need a rigorous lab-science foundation without assuming a single major track.", "topics": [{"id": "a8d85716-2953-4854-ae9e-3730b916231d", "type": "topic", "title": "Science as a Way of Knowing", "description": "This opening unit frames natural science as a disciplined way of asking questions about the physical, chemical, biological, and Earth systems around us. Students learn that science is not a list of facts; it is a method for building, testing, revising, and communicating explanations.", "children": [{"id": "b2a1e4c2-a850-4561-a0f8-98dd9306af9f", "type": "subtopic", "title": "Observation, inference, and explanation", "children": [{"id": "e6c4adf6-11cc-4e74-b8d2-3c25b1034145", "type": "concept", "title": "Qualitative and quantitative observations"}, {"id": "2be70b78-1b88-4d70-aae0-05a0cd472fea", "type": "concept", "title": "Inference versus assumption"}, {"id": "c0571489-96b9-4c0c-8013-462c48ab56f4", "type": "concept", "title": "Evidence-based explanation"}], "description": "Students learn to separate what is directly observed from the interpretations and models built from those observations."}, {"id": "7053c5b9-19d0-4cba-a099-354b4b1348d5", "type": "subtopic", "title": "The scientific method and scientific inquiry", "children": [{"id": "2851f60f-1fc2-4eb0-913b-506ed1f4d336", "type": "concept", "title": "Questions and hypotheses"}, {"id": "ae70a99c-abed-4e72-87be-3768859429aa", "type": "concept", "title": "Prediction and testability"}, {"id": "ca590bb5-ef1a-4ede-93e6-d183aee11a60", "type": "concept", "title": "Iteration and revision"}], "description": "This subtopic introduces the cycle of questioning, prediction, testing, analysis, and revision used across laboratory sciences."}, {"id": "7b43adc7-9606-4201-a5d1-aff00c5d6595", "type": "subtopic", "title": "Scientific literacy and source evaluation", "children": [{"id": "915edbe3-64cd-4ed3-b353-dce8f351b1dc", "type": "concept", "title": "Peer review and authority"}, {"id": "6f081c34-cb35-4ecc-9b15-38c12cce05db", "type": "concept", "title": "Correlation, causation, and overclaiming"}, {"id": "637a0913-e93c-4fda-aa63-e80a6c445380", "type": "concept", "title": "Science news and misinformation"}], "description": "Students practice reading scientific claims carefully, identifying credible sources, and recognizing uncertainty in public science communication."}]}, {"id": "f97911e6-26a4-446a-ab80-b1a7c5293822", "type": "topic", "title": "Measurement, Units, Uncertainty, and Significant Figures", "description": "Laboratory science depends on careful measurement. This unit gives students the habits needed to collect data that are meaningful, comparable, and honest about their limits.", "children": [{"id": "b03e72c0-b55d-4027-9c2d-df735d27c7ad", "type": "subtopic", "title": "Units and dimensional reasoning", "children": [{"id": "6f8c86b8-fe4f-40c0-a4b3-94639f677bae", "type": "concept", "title": "SI base and derived units"}, {"id": "ab09423b-3387-4583-ac32-b1466b61ba61", "type": "concept", "title": "Unit conversion and dimensional checks"}, {"id": "54900379-2db3-4f2d-931a-81a24f99db15", "type": "concept", "title": "Orders of magnitude and scale"}], "description": "Students learn to use SI units, unit conversions, dimensional analysis, and scale reasoning as basic tools for scientific problem solving."}, {"id": "cd31ca29-d5f9-4fcc-b4eb-de91131dd6c0", "type": "subtopic", "title": "Accuracy, precision, and uncertainty", "children": [{"id": "01e87790-8ba5-4fe2-8c54-779e47c849a1", "type": "concept", "title": "Systematic and random error"}, {"id": "9af4e36f-0422-4c8b-bda1-60c3d0ddbf81", "type": "concept", "title": "Instrument resolution"}, {"id": "f940aaf5-9227-40a9-8c92-c1d722f91171", "type": "concept", "title": "Uncertainty intervals"}], "description": "This subtopic teaches students to distinguish closeness to the true value from repeatability, and to communicate uncertainty appropriately."}, {"id": "ec597121-a78c-48c6-a3f9-3b6674082a19", "type": "subtopic", "title": "Significant figures and scientific notation", "children": [{"id": "d9c72aa8-9c13-4e78-add7-306e23ec6de9", "type": "concept", "title": "Rounding rules"}, {"id": "c5724b93-17d4-466e-97fe-ab316dce0deb", "type": "concept", "title": "Propagation in simple calculations"}, {"id": "3a6d6230-75b2-4fd1-a7aa-00e1a006799f", "type": "concept", "title": "Scientific notation in lab records"}], "description": "Students learn how reported numbers carry information about measurement quality and how to avoid false precision."}]}, {"id": "59eb633b-17b2-41e8-9d5b-c3fc7b365819", "type": "topic", "title": "Laboratory Safety, Ethics, and Scientific Responsibility", "description": "This lab course treats safety and ethics as core scientific skills. Students learn how to protect themselves, classmates, organisms, communities, and the integrity of the evidence they produce.", "children": [{"id": "9218b0f5-c2e6-4fe9-9107-6ed813a08016", "type": "subtopic", "title": "Safety culture and hazard recognition", "children": [{"id": "5fa4ce3d-1994-4ec4-b080-c8569edc0edf", "type": "concept", "title": "Safety Data Sheets"}, {"id": "8aad9f44-0774-4bcf-9ca8-9d161a2b9bf4", "type": "concept", "title": "PPE and engineering controls"}, {"id": "17683a89-7019-4e3f-a6e0-e28bcfeed473", "type": "concept", "title": "Emergency response basics"}], "description": "Students learn to identify physical, chemical, biological, and environmental hazards before beginning any experiment."}, {"id": "ffc27d55-9877-4f2f-a532-36ee6a11f004", "type": "subtopic", "title": "Ethical conduct in the laboratory", "children": [{"id": "3256e356-9838-4e64-97af-c557fc1ea0cd", "type": "concept", "title": "Data integrity"}, {"id": "9ba1d008-06e5-4b7f-ae6c-3f1d4e9dc38f", "type": "concept", "title": "Authorship and collaboration"}, {"id": "e322cf40-ac6e-4a6f-aa0a-a66702593ef7", "type": "concept", "title": "Animal, human, and environmental considerations"}], "description": "This subtopic introduces honesty in data recording, responsible collaboration, respect for living systems, and appropriate handling of uncertainty."}, {"id": "8c62a132-f8f0-417b-8101-92c17387fd82", "type": "subtopic", "title": "Waste, contamination, and sustainability", "children": [{"id": "456eee2c-ac04-4e53-bd2e-a7ba63d2f72c", "type": "concept", "title": "Chemical and biological waste streams"}, {"id": "e8cb7b5b-ec99-4313-a371-231fe46ff5d6", "type": "concept", "title": "Cross-contamination prevention"}, {"id": "0d3adc24-2fd2-48a4-b2fb-f56ac7975685", "type": "concept", "title": "Green chemistry and resource stewardship"}], "description": "Students learn that lab work has material consequences and that safe disposal and contamination control are part of responsible science."}]}, {"id": "21a9c99a-b44c-46e2-9276-ad8bda356a28", "type": "topic", "title": "Experimental Design and Hypothesis Testing", "description": "Students move from curiosity to controlled investigation. This unit teaches them how to design experiments that can actually answer a question, not merely produce activity.", "children": [{"id": "7aa001cc-5339-4933-8fe6-d297704415f0", "type": "subtopic", "title": "Variables, controls, and comparisons", "children": [{"id": "24d9b532-c158-454e-acc7-e2faf3ea0b1e", "type": "concept", "title": "Independent and dependent variables"}, {"id": "2ca22a37-1998-4135-aa45-165d13b20404", "type": "concept", "title": "Positive and negative controls"}, {"id": "1b4a0f4b-f98b-46d9-a46f-78698fea0438", "type": "concept", "title": "Confounding variables"}], "description": "Students learn how independent variables, dependent variables, control groups, constants, and comparison conditions shape interpretability."}, {"id": "a9448686-5c4d-43c8-a523-3517e9382e0c", "type": "subtopic", "title": "Hypothesis testing in practice", "children": [{"id": "0b65a94c-6c59-4abd-918d-3ee94342e1e0", "type": "concept", "title": "Null and alternative hypotheses"}, {"id": "4bd901bc-6484-478e-a1fc-033a12d4a10d", "type": "concept", "title": "Operational definitions"}, {"id": "e68d2c89-c6e9-4f03-8b6c-516d4a9ffdaf", "type": "concept", "title": "Criteria for evidence"}], "description": "This subtopic turns hypotheses into testable predictions and introduces the logic of rejecting, supporting, or revising explanations."}, {"id": "275e6ae6-4738-4404-a60c-e05a157839c8", "type": "subtopic", "title": "Replication and reproducibility", "children": [{"id": "e8cbb202-7b0b-4808-b215-c335c4d97c5a", "type": "concept", "title": "Technical and biological replicates"}, {"id": "bcbf821b-fc30-4b6d-99c1-d83a97460a89", "type": "concept", "title": "Protocol clarity"}, {"id": "a3caccf3-103a-4a4e-8560-e69430bd129a", "type": "concept", "title": "Reproducible workflows"}], "description": "Students learn why repeated trials, transparent protocols, and reproducible methods matter for trustworthy science."}]}, {"id": "0cf03372-9cb9-4311-a256-52c95eda0473", "type": "topic", "title": "Data Collection, Statistics, and Visualization", "description": "This unit equips students to transform raw observations into interpretable evidence. They learn the basics of organizing data, summarizing variation, visualizing patterns, and making careful claims.", "children": [{"id": "625f6f28-649b-4762-b2b8-2b2ab4d63f55", "type": "subtopic", "title": "Data tables and metadata", "children": [{"id": "c3029ad4-712a-4a8d-816b-4fc6ec55de07", "type": "concept", "title": "Tidy data principles"}, {"id": "5f6bb10e-8ec0-417e-86a0-b11cab6b6ad9", "type": "concept", "title": "Metadata and labels"}, {"id": "03388b72-04a6-4603-afde-e8dc4cc4c092", "type": "concept", "title": "Lab notebook conventions"}], "description": "Students learn to organize lab data so another person could understand what was measured, how, when, and under what conditions."}, {"id": "3dab4d23-3d37-46fc-927f-f723ef62b417", "type": "subtopic", "title": "Descriptive statistics and error bars", "children": [{"id": "1c6e7328-848c-4bbc-8410-ef5e7182232f", "type": "concept", "title": "Central tendency"}, {"id": "45135314-3dd8-462a-8794-c97d53d88105", "type": "concept", "title": "Variation and spread"}, {"id": "07300e79-ac8f-4773-ae67-b0cc664889db", "type": "concept", "title": "Uncertainty visualization"}], "description": "This subtopic introduces means, medians, ranges, standard deviation, standard error, and confidence intervals at an introductory level."}, {"id": "7c50af6b-6b5f-4b21-a2fb-036e698a5e46", "type": "subtopic", "title": "Graphs and scientific storytelling", "children": [{"id": "907626b9-fd9f-4975-b337-ed268528ecc8", "type": "concept", "title": "Scatterplots and line graphs"}, {"id": "20b2b068-7987-4e4c-868c-33a1aa096c31", "type": "concept", "title": "Bar charts and boxplots"}, {"id": "b0061995-aed5-4d68-b223-961ca9a3f0ef", "type": "concept", "title": "Axis labels, captions, and visual integrity"}], "description": "Students practice choosing the right visual form and avoiding misleading charts."}]}, {"id": "cf24eebf-7ab0-4364-9b04-25c4a46a6616", "type": "topic", "title": "Matter, Atoms, Molecules, and Chemical Change", "description": "Chemistry provides the language of matter and transformation. This unit gives students enough chemical foundation to understand substances, reactions, solutions, and laboratory analysis.", "children": [{"id": "e0bb7d01-970b-419a-97fc-d2dcc8c8afed", "type": "subtopic", "title": "Atomic structure and periodic patterns", "children": [{"id": "85b90c99-8239-44ce-b041-79f4b61c3ca2", "type": "concept", "title": "Protons, neutrons, and electrons"}, {"id": "2e758182-7e8c-418e-b35b-026a02a60519", "type": "concept", "title": "Electron configuration"}, {"id": "e56425fc-d7f7-4073-bec5-7dec844c00b8", "type": "concept", "title": "Periodic trends"}], "description": "Students connect atomic structure to periodic trends and the behavior of elements."}, {"id": "8eb2e90c-ed83-4d75-9747-604e4ef535f4", "type": "subtopic", "title": "Bonding, molecules, and intermolecular forces", "children": [{"id": "7d8482df-2494-4490-9170-2aa9197e4e1c", "type": "concept", "title": "Ionic and covalent bonding"}, {"id": "edbcccec-9492-4fdf-b123-422ef5de6541", "type": "concept", "title": "Molecular geometry"}, {"id": "b26840c1-39b3-487f-b920-f1042b213056", "type": "concept", "title": "Polarity and intermolecular forces"}], "description": "This subtopic explains how atoms combine and why molecular structure influences properties."}, {"id": "985fe37e-0c60-4a90-bf6b-f557d84bfdf6", "type": "subtopic", "title": "Chemical reactions and stoichiometry", "children": [{"id": "5f90e26b-0ef9-44e5-8878-6f37c26f88c0", "type": "concept", "title": "Balanced equations"}, {"id": "a5506083-e2d7-41aa-9e9d-f81fdd9b076a", "type": "concept", "title": "Moles and molar mass"}, {"id": "0447dd1b-15cd-4832-8a5d-5896c97b04b8", "type": "concept", "title": "Limiting reactants and yield"}], "description": "Students learn to represent reactions, balance equations, and reason quantitatively about reactants and products."}]}, {"id": "8d8042b1-8bf6-4530-9546-cfe790115700", "type": "topic", "title": "Energy, Thermodynamics, and Transformations", "description": "Energy links physics, chemistry, biology, and Earth systems. This unit helps students track how energy is stored, transferred, degraded, and conserved across natural processes.", "children": [{"id": "699efd77-d965-4cb9-978b-165b1a5d8b25", "type": "subtopic", "title": "Forms of energy and conservation", "children": [{"id": "41d69e2b-9489-443b-9973-a6b912b1038d", "type": "concept", "title": "Conservation of energy"}, {"id": "deacb950-8923-4597-9bc3-abf1704d6967", "type": "concept", "title": "Energy transfer and transformation"}, {"id": "489157c9-595f-4246-9712-a69d0b22ed1e", "type": "concept", "title": "System boundaries"}], "description": "Students learn to identify kinetic, potential, thermal, chemical, electrical, and radiant energy in systems."}, {"id": "ba29917a-3818-4742-b540-ac68d075e0d0", "type": "subtopic", "title": "Heat, temperature, and thermodynamics", "children": [{"id": "5d1714c6-7194-4942-9cfd-5b62c2de2049", "type": "concept", "title": "Temperature versus heat"}, {"id": "f895cb3e-5441-4992-af4b-ecac2e3f77f8", "type": "concept", "title": "Calorimetry"}, {"id": "1a685779-1cd2-404c-b66f-60752a6563ee", "type": "concept", "title": "Entropy and spontaneity"}], "description": "This subtopic introduces temperature, heat flow, specific heat, phase changes, and entropy as practical lab ideas."}, {"id": "8d786368-a16f-49f0-9f34-805c93275888", "type": "subtopic", "title": "Energy in living and environmental systems", "children": [{"id": "dd1d0b85-0aec-4eb9-bb36-16343f1104bf", "type": "concept", "title": "Cellular respiration and photosynthesis"}, {"id": "cf983d7c-c9c9-4e09-9adc-607e20aaeb5e", "type": "concept", "title": "Food webs and trophic efficiency"}, {"id": "df389f16-8313-4881-a113-1b65ca8669c3", "type": "concept", "title": "Radiation balance and greenhouse effect"}], "description": "Students connect thermodynamic principles to metabolism, photosynthesis, ecosystems, and climate."}]}, {"id": "1137fc08-a609-4261-bd95-372115634a7e", "type": "topic", "title": "Forces, Motion, Waves, and Physical Systems", "description": "Physics gives students tools for analyzing motion, force, energy, waves, and interactions. This unit emphasizes measurable relationships and model-based reasoning.", "children": [{"id": "958f0ad5-4292-4168-b430-56a223ec1da1", "type": "subtopic", "title": "Motion and force models", "children": [{"id": "9bcc0288-21b5-4d53-a1e4-da6811007226", "type": "concept", "title": "Position, velocity, and acceleration"}, {"id": "9ad0261b-466d-48a0-b6b9-5b69dbe84b10", "type": "concept", "title": "Free-body diagrams"}, {"id": "e93de870-c456-4859-9f1a-579b368e8a87", "type": "concept", "title": "Newton's laws"}], "description": "Students use graphs, vectors, and Newton's laws to describe and explain motion."}, {"id": "79ea8b03-a943-4edf-87c3-7e00f698605a", "type": "subtopic", "title": "Work, energy, and momentum", "children": [{"id": "481a1690-d2ca-4850-a679-023eac033706", "type": "concept", "title": "Work and kinetic energy"}, {"id": "3b3fd180-b971-4828-8dfa-ee761ccf5bc5", "type": "concept", "title": "Potential energy"}, {"id": "5bf264cc-5029-4e7e-a98c-8261574cc96f", "type": "concept", "title": "Momentum and impulse"}], "description": "This subtopic connects physical interactions with conservation principles and measurable system changes."}, {"id": "a46320fd-3fa8-4609-aaef-1930dfaf0cca", "type": "subtopic", "title": "Waves and oscillations", "children": [{"id": "5dacd4e3-4182-456f-ae7a-2f159442e238", "type": "concept", "title": "Frequency, wavelength, and amplitude"}, {"id": "99eea32f-f2ae-4136-8133-806ebdd93380", "type": "concept", "title": "Interference and resonance"}, {"id": "fcfb773c-db25-4eee-a07a-df623fee3b95", "type": "concept", "title": "Sound and light as waves"}], "description": "Students study wave properties that connect sound, light, water waves, seismic motion, and instrumentation."}]}, {"id": "d66e2807-7466-4021-94b9-dbf42a4b872b", "type": "topic", "title": "Electricity, Magnetism, Light, and Instrumentation", "description": "Modern lab science depends on instruments that convert physical interactions into measurable signals. This unit introduces basic electricity, magnetism, optics, and sensors.", "children": [{"id": "ef4cd5f6-3b70-439b-9185-d7941ac78d60", "type": "subtopic", "title": "Electric circuits and measurement", "children": [{"id": "e2f4e20c-2cac-483b-98f1-d110967e7f8b", "type": "concept", "title": "Ohm's law"}, {"id": "033bf22c-1f0a-45b3-8bc3-f84da9207aa8", "type": "concept", "title": "Series and parallel circuits"}, {"id": "7e611b52-b1a2-47c9-aeac-d91cfc954277", "type": "concept", "title": "Multimeters and sensors"}], "description": "Students learn how voltage, current, resistance, and simple circuits support measurement and instrumentation."}, {"id": "d5e1d034-bab7-4736-8622-6a4a9d4fd6dc", "type": "subtopic", "title": "Magnetism and electromagnetic induction", "children": [{"id": "a534ff69-a511-411a-8fa2-702ba297adee", "type": "concept", "title": "Magnetic fields"}, {"id": "7a4d3d4a-2018-44b2-9194-579eae1562a5", "type": "concept", "title": "Electromagnetic induction"}, {"id": "13d217c5-4dbc-4362-bf47-f515019e5c08", "type": "concept", "title": "Motors and generators"}], "description": "This subtopic introduces the relationships among currents, fields, induction, generators, and common instruments."}, {"id": "672dcb3b-2ff6-45d4-b541-0c2756249087", "type": "subtopic", "title": "Light, optics, and spectroscopy", "children": [{"id": "8e34154d-feac-4829-aecf-e4fbf71d8ed8", "type": "concept", "title": "Reflection and refraction"}, {"id": "4e4cbd39-cad1-4b76-a6ff-d8c7eb612c13", "type": "concept", "title": "Lenses and image formation"}, {"id": "34002e83-8335-4b24-840e-12fc08507cc4", "type": "concept", "title": "Absorption and emission spectra"}], "description": "Students connect light behavior to microscopy, cameras, colorimetry, spectrophotometry, and remote sensing."}]}, {"id": "bfea3b82-3ef7-4811-86f0-70bc24a14a7c", "type": "topic", "title": "Cells, Biomolecules, and Microscopy", "description": "Biology begins with the cell as the basic unit of life. This unit links molecular structure, cellular organization, microscopy, and experimental observation.", "children": [{"id": "d906507e-2c88-4afd-b97a-9a7ce5d71978", "type": "subtopic", "title": "Biomolecules and water", "children": [{"id": "1029ed90-3d70-458a-8da4-d1926128296e", "type": "concept", "title": "Water properties"}, {"id": "432eeab5-94d2-4af0-849a-dd2abafb58f2", "type": "concept", "title": "Macromolecule structure and function"}, {"id": "2033ca73-b867-4b23-8a46-a8e3231439e1", "type": "concept", "title": "Enzymes and catalysis"}], "description": "Students learn how carbohydrates, lipids, proteins, nucleic acids, and water support life processes."}, {"id": "1dd45f41-4b7d-40bf-b3f6-02d784d42381", "type": "subtopic", "title": "Cell structure and function", "children": [{"id": "39d5acf3-ca08-4802-8ec4-1f87824ceacd", "type": "concept", "title": "Prokaryotic and eukaryotic cells"}, {"id": "d787e0c5-3eab-4a86-96ff-83826b392fbf", "type": "concept", "title": "Membranes and transport"}, {"id": "08b68e9f-ec58-4df6-a619-e6d39ea10fef", "type": "concept", "title": "Organelles and compartmentalization"}], "description": "This subtopic introduces membranes, organelles, cell specialization, and transport."}, {"id": "6c96a8a4-3dc0-4b83-ae57-86124315beb6", "type": "subtopic", "title": "Microscopy and biological observation", "children": [{"id": "ac4832bf-813d-4d52-932c-b2eee7197ed4", "type": "concept", "title": "Light microscopy"}, {"id": "b95ecc32-bf41-41c7-8987-2f146edbd1db", "type": "concept", "title": "Magnification and resolution"}, {"id": "738c12c9-b1cc-44c2-9b41-93d54600f7f8", "type": "concept", "title": "Staining and specimen preparation"}], "description": "Students learn to prepare specimens, use microscopes responsibly, and connect image evidence to biological claims."}]}, {"id": "0777f579-6061-487d-ba7b-65a616ccf1d7", "type": "topic", "title": "Genetics, Evolution, and Biodiversity", "description": "This unit connects inheritance, variation, natural selection, and the diversity of life. Students learn how biological patterns emerge across generations and ecosystems.", "children": [{"id": "08201665-7fe8-4b12-b802-78fa361da1b0", "type": "subtopic", "title": "DNA, genes, and inheritance", "children": [{"id": "e32c0167-62aa-4097-a784-766674eadaf4", "type": "concept", "title": "DNA structure and replication"}, {"id": "40e981cc-e674-4157-b640-5dcbf7a9e32f", "type": "concept", "title": "Transcription and translation"}, {"id": "41083dd9-8947-4bbe-8d8c-f73f1ae3f185", "type": "concept", "title": "Mendelian inheritance"}], "description": "Students learn the basic flow of genetic information and how traits are transmitted and expressed."}, {"id": "07b4470d-1068-483a-aec2-b031b74450b8", "type": "subtopic", "title": "Evolution and natural selection", "children": [{"id": "f178f412-a668-471f-94c7-955f5ab675e2", "type": "concept", "title": "Variation and fitness"}, {"id": "a5fcaf49-676e-4d36-afd3-615f8daeb2a2", "type": "concept", "title": "Natural selection"}, {"id": "963669d7-56d9-4b21-977e-14871996fa7b", "type": "concept", "title": "Speciation and phylogeny"}], "description": "This subtopic explains how heritable variation, differential survival, and reproduction shape populations over time."}, {"id": "b630cc9f-6ab2-499f-bf43-1ea502ea09cb", "type": "subtopic", "title": "Biodiversity and classification", "children": [{"id": "d99a5ee3-6e36-47db-b4f3-fbc0ebb82edd", "type": "concept", "title": "Domains and kingdoms"}, {"id": "b840a2af-896a-463c-9505-14eae1dd85f5", "type": "concept", "title": "Phylogenetic trees"}, {"id": "f6ff7690-7b9d-465b-b42d-b0f1bdbe74b3", "type": "concept", "title": "Biodiversity measurement"}], "description": "Students learn why biodiversity matters scientifically and practically, and how organisms are classified."}]}, {"id": "81a8fb60-490e-44ec-a7c6-933b37bcc23b", "type": "topic", "title": "Ecology, Earth Systems, and Environmental Change", "description": "Natural science is strongest when students can connect organisms, matter, energy, Earth processes, and human impacts. This unit integrates ecology and environmental science.", "children": [{"id": "10c89314-3222-453f-b308-7aaedf77d17a", "type": "subtopic", "title": "Ecosystems and biogeochemical cycles", "children": [{"id": "7ff72550-a2b0-4361-abf0-0970a529c09b", "type": "concept", "title": "Carbon, nitrogen, phosphorus, and water cycles"}, {"id": "b75c2a8b-bd9e-48a2-9149-140c6a65e890", "type": "concept", "title": "Food webs"}, {"id": "c11feaac-a8fa-4067-bd35-f264bb415176", "type": "concept", "title": "Primary productivity"}], "description": "Students learn how matter and energy move through ecosystems and Earth systems."}, {"id": "035315b7-4666-4920-b9d9-4427f589186a", "type": "subtopic", "title": "Climate, weather, and Earth observations", "children": [{"id": "c3fc1926-c777-4de0-8666-55ba7a558bc3", "type": "concept", "title": "Atmosphere and ocean interactions"}, {"id": "019cdc42-052e-462d-94ce-5c83c05b8c05", "type": "concept", "title": "Climate versus weather"}, {"id": "4447fc54-2599-455e-beeb-2e6b6879bf9a", "type": "concept", "title": "Remote sensing and climate records"}], "description": "This subtopic introduces climate drivers, weather patterns, satellite observation, and long-term environmental data."}, {"id": "3d1785f2-5d8c-457a-b7a0-b867cf4bdbac", "type": "subtopic", "title": "Human impacts and sustainability", "children": [{"id": "53333cff-8574-4d33-8a52-ac18d3b502cc", "type": "concept", "title": "Pollution pathways"}, {"id": "e65dae4e-adc9-469c-bda0-7a5c5a064edd", "type": "concept", "title": "Resource use and waste"}, {"id": "a2e76b6b-49c1-4096-af3e-e777b5ea16ff", "type": "concept", "title": "Sustainability and resilience"}], "description": "Students examine pollution, land use, resource consumption, biodiversity loss, and solutions grounded in evidence."}]}, {"id": "4d66f5c6-7cc2-49f6-906f-7eada4f8aa1a", "type": "topic", "title": "Water, Air, Soil, and Field Methods", "description": "Field science asks students to measure real systems outside highly controlled lab conditions. This unit introduces practical sampling, environmental monitoring, and field-data interpretation.", "children": [{"id": "f1ad072d-7118-4036-9b6c-aea6222274ae", "type": "subtopic", "title": "Sampling design in the field", "children": [{"id": "84d28459-77ce-402a-b7dd-c6f02588b7b5", "type": "concept", "title": "Transects and quadrats"}, {"id": "7f30642c-b2ef-41d1-b566-31269df93a7e", "type": "concept", "title": "Random and stratified sampling"}, {"id": "50b4489c-1ee6-493f-86d8-177eaf2e5c05", "type": "concept", "title": "Spatial and temporal variation"}], "description": "Students learn how location, timing, replication, and sampling bias shape conclusions about natural systems."}, {"id": "ae5edcf6-69b6-4c79-8803-4c7e1cfa30f4", "type": "subtopic", "title": "Water and soil measurements", "children": [{"id": "216e59d6-8994-49d3-bd89-756d9eb4ce70", "type": "concept", "title": "pH, conductivity, and dissolved oxygen"}, {"id": "5f4f062f-5f99-4bc7-908f-2c7f3b0b5946", "type": "concept", "title": "Turbidity and nutrients"}, {"id": "2f048337-7c38-40c1-a428-c1792e800ff0", "type": "concept", "title": "Soil texture and moisture"}], "description": "This subtopic introduces common field and bench measurements used in environmental science."}, {"id": "e3b0b127-e3ed-4c24-adf0-8bad618f795f", "type": "subtopic", "title": "Air, weather, and microclimate data", "children": [{"id": "037929db-8095-4498-a89e-90c41efe6178", "type": "concept", "title": "Temperature, humidity, and pressure"}, {"id": "90c1f0ca-1be7-4443-af2e-e09c6e310bc9", "type": "concept", "title": "Wind and precipitation"}, {"id": "08d82b6e-a98c-4700-8cb5-91f20b389337", "type": "concept", "title": "Particulates and air quality indicators"}], "description": "Students connect local atmospheric measurements to larger environmental processes."}]}, {"id": "7ba3eb3a-f68f-4c76-8afb-2ca37a2eb882", "type": "topic", "title": "Core Laboratory Techniques Across the Sciences", "description": "Students need a practical toolkit that transfers across biology, chemistry, physics, and environmental laboratories. This unit focuses on technique, calibration, and disciplined execution.", "children": [{"id": "8f0205e5-7e0d-4e2c-97e7-58bcd1e31f39", "type": "subtopic", "title": "Mass, volume, and solution preparation", "children": [{"id": "04eee5c3-173c-4239-82ca-b1a89d1c0949", "type": "concept", "title": "Balances and weighing"}, {"id": "d638c13a-c79c-4b6d-9d43-fdb0e6c7b460", "type": "concept", "title": "Pipettes and volumetric glassware"}, {"id": "1e1c9e1f-43b3-457f-898d-52459fc9063a", "type": "concept", "title": "Molarity and dilution"}], "description": "Students learn the basic manipulations behind reliable chemical and biological lab work."}, {"id": "f0cedf9b-774a-4508-8065-b6b943a159a3", "type": "subtopic", "title": "Separation and identification methods", "children": [{"id": "6bf893a3-1986-4460-8ce1-d042a255ca11", "type": "concept", "title": "Filtration and centrifugation"}, {"id": "71a721ed-17d9-4351-a4d6-178fc01be8d5", "type": "concept", "title": "Chromatography"}, {"id": "93a37594-d83e-4fc9-9621-3d73b06c4a02", "type": "concept", "title": "Spectrophotometry"}], "description": "This subtopic introduces common methods for separating, identifying, or quantifying components of mixtures."}, {"id": "cd779174-74a9-4383-a8cc-1548ad96e987", "type": "subtopic", "title": "Calibration and quality control", "children": [{"id": "6cd0d211-ccd6-4440-8065-345861b31061", "type": "concept", "title": "Calibration curves"}, {"id": "c89ca6d0-2ae8-4d4c-9f7b-7970ff503502", "type": "concept", "title": "Blanks and standards"}, {"id": "ca53a560-8c23-450c-93d3-34e47cf46a8a", "type": "concept", "title": "Quality control samples"}], "description": "Students learn that instruments and methods must be checked against standards before data can be trusted."}]}, {"id": "4ae9ac8b-3262-40b9-b2eb-31c1eb76f4c9", "type": "topic", "title": "Models, Simulations, and Computational Thinking", "description": "Models help scientists reason about systems too small, large, fast, slow, dangerous, or complex to observe directly. This unit introduces conceptual, mathematical, physical, and computational models.", "children": [{"id": "42209c17-431a-4db0-b375-8abc4182e7cd", "type": "subtopic", "title": "Conceptual and mathematical models", "children": [{"id": "540a772d-5cc6-491a-9bcb-db8065cc8df6", "type": "concept", "title": "Assumptions and simplifications"}, {"id": "20b71005-18fc-4a7e-a895-9042c88fdf42", "type": "concept", "title": "Variables and parameters"}, {"id": "ff9b4500-8cdf-4e4a-8be7-4ad0e622da8b", "type": "concept", "title": "Model validation"}], "description": "Students learn how models simplify reality while preserving relationships useful for prediction and explanation."}, {"id": "94fca541-ea69-48fb-a19c-354daf7c420a", "type": "subtopic", "title": "Interactive simulations", "children": [{"id": "dfd24be1-43a8-472a-b7e7-3f926eeb5b28", "type": "concept", "title": "Parameter exploration"}, {"id": "8790039d-0d28-46a4-8bff-f602897de3a5", "type": "concept", "title": "Virtual experiments"}, {"id": "053e440d-39d4-4ea7-95c5-3148f2f9ab1f", "type": "concept", "title": "Model limitations"}], "description": "This subtopic uses simulation tools to explore systems such as circuits, molecules, populations, climate, and waves."}, {"id": "63f9c333-3edd-4dfb-9769-8a7b866ab445", "type": "subtopic", "title": "Computational data habits", "children": [{"id": "1dc89d55-35f7-4543-aa8f-7a1577d65a65", "type": "concept", "title": "Formulas and data cleaning"}, {"id": "be74203c-d5b2-4d49-839d-d4918e22dd86", "type": "concept", "title": "Versioned files"}, {"id": "c237eac8-dbc2-4768-9edc-93c0ac847298", "type": "concept", "title": "Reproducible plots"}], "description": "Students build basic comfort with spreadsheets or notebooks for calculation, plotting, and reproducible analysis."}]}, {"id": "eed35d3c-6b45-4fbb-a96b-08cf4c3ae777", "type": "topic", "title": "Scientific Communication and Lab Reports", "description": "Science becomes useful when methods, evidence, uncertainty, and conclusions are communicated clearly. This unit teaches students to write and present like beginning scientists.", "children": [{"id": "2aee6750-6026-417d-ae56-e23f36b11da6", "type": "subtopic", "title": "Lab report structure", "children": [{"id": "49d5843d-7d2e-4afe-a846-e3932dfe97df", "type": "concept", "title": "Research question and rationale"}, {"id": "e50ed541-79cd-49e7-915a-733128d07a51", "type": "concept", "title": "Methods detail and reproducibility"}, {"id": "6cf2b9f6-acf8-49ee-bbaa-746a5e804260", "type": "concept", "title": "Results versus interpretation"}], "description": "Students learn the purpose of each section: abstract, introduction, methods, results, discussion, conclusion, and references."}, {"id": "146512c2-af7e-40d5-8f83-097f32bbf292", "type": "subtopic", "title": "Figures, tables, and captions", "children": [{"id": "68d987d2-da6e-4345-a875-2cdb6c3ce84b", "type": "concept", "title": "Figure captions"}, {"id": "f53e46c0-1aae-4e6b-b0d5-764a6a875e74", "type": "concept", "title": "Table design"}, {"id": "d939fffc-5039-4996-90ee-b991535201ee", "type": "concept", "title": "Error bars and notes"}], "description": "This subtopic teaches students to present data so readers can understand the claim without guessing."}, {"id": "cfce8a83-dad3-4363-94a1-438c47236206", "type": "subtopic", "title": "Argument, citation, and revision", "children": [{"id": "284d2660-20f9-458c-ba20-f3e892baebbc", "type": "concept", "title": "Claim-evidence-reasoning"}, {"id": "a0e010f0-b0b3-4cae-ac54-fd681cba594d", "type": "concept", "title": "Citation basics"}, {"id": "3e9140e6-4687-40c3-8250-11320d0d6737", "type": "concept", "title": "Peer review and revision"}], "description": "Students learn to support conclusions with evidence, cite sources, and improve work through feedback."}]}, {"id": "f262dd9c-78fa-47d0-979a-1286a9c9a110", "type": "topic", "title": "Science, Society, Risk, and Decision-Making", "description": "Natural science informs real decisions about health, technology, climate, energy, food, water, and safety. This unit helps students connect evidence to public choices without oversimplifying uncertainty.", "children": [{"id": "1064ea22-7570-4b76-a802-70e987add980", "type": "subtopic", "title": "Risk, probability, and uncertainty", "children": [{"id": "c865c90b-f595-4b74-9a7d-2897404850a8", "type": "concept", "title": "Hazard versus risk"}, {"id": "1b8f9991-3340-4481-aa6d-4f8feb18c95a", "type": "concept", "title": "Dose-response thinking"}, {"id": "ed940695-7d02-49f7-9270-f27dc27a0c96", "type": "concept", "title": "Precaution and tradeoffs"}], "description": "Students learn how scientists and decision-makers reason about likelihood, consequence, exposure, and uncertainty."}, {"id": "08c9c507-aef6-4d4c-8a31-bebbe991f390", "type": "subtopic", "title": "Science policy and public trust", "children": [{"id": "cfbe2a35-2c5b-4cc4-aa1c-0bacc4a7802a", "type": "concept", "title": "Regulation and standards"}, {"id": "20120dd0-4988-4e2c-801a-d7b2efb7bac7", "type": "concept", "title": "Expertise and public communication"}, {"id": "66f24063-4f10-4432-9357-6aa40071ae45", "type": "concept", "title": "Conflicts of interest"}], "description": "This subtopic examines how scientific evidence moves through agencies, media, communities, and policy debates."}, {"id": "ec22c161-7b64-416f-830f-391e2a4a5a75", "type": "subtopic", "title": "Current scientific issues", "children": [{"id": "af5d6f4e-472c-4cb2-883f-c0ef0408d113", "type": "concept", "title": "Climate and energy transitions"}, {"id": "31e1e547-4f3f-427c-ba0b-f86f20c92eb0", "type": "concept", "title": "Water quality and public health"}, {"id": "1b2106ff-52c0-485e-b5c4-8ee830b3b108", "type": "concept", "title": "Biotechnology and emerging technologies"}], "description": "Students apply course tools to contemporary issues where biology, chemistry, physics, and environmental science intersect."}]}, {"id": "f89380f1-a2b4-4515-94f0-ea7d5348b7d1", "type": "topic", "title": "Integrated Capstone Lab Investigation", "description": "The course culminates in an investigation where students ask a question, design a method, collect data, analyze uncertainty, and communicate results. The goal is to practice science as a complete workflow.", "children": [{"id": "e84671c0-7882-4035-8012-735c17633ba7", "type": "subtopic", "title": "Question, background, and design proposal", "children": [{"id": "e4b8c070-4a91-47da-a42d-2a0c63e0ea40", "type": "concept", "title": "Researchable question"}, {"id": "5c1b973b-d3eb-4f94-b82e-73a43aa9199a", "type": "concept", "title": "Background source map"}, {"id": "e9b234c1-da83-4445-8fed-251789311b38", "type": "concept", "title": "Variables, controls, and safety plan"}], "description": "Students formulate a focused question, review relevant concepts, and propose a safe, feasible investigation."}, {"id": "ee73a0b1-5c86-4108-bba8-4b91cd381699", "type": "subtopic", "title": "Data collection and analysis", "children": [{"id": "6d5504e3-d668-45f1-bd7c-e21b65a30dd9", "type": "concept", "title": "Protocol execution"}, {"id": "5e523657-f97b-4ec2-ba5b-77e93e377199", "type": "concept", "title": "Data cleaning and analysis"}, {"id": "5011f611-edc3-4ed2-b18d-ef8b5a72f306", "type": "concept", "title": "Uncertainty and error evaluation"}], "description": "This subtopic guides students through careful measurement, troubleshooting, statistical summary, and visualization."}, {"id": "b87787ce-6b54-44ff-aa7a-b8d5e98c4efd", "type": "subtopic", "title": "Poster, report, and reflection", "children": [{"id": "458b7284-4f0f-4332-b578-1e59c72e2c08", "type": "concept", "title": "Scientific poster or report"}, {"id": "a356d862-c76d-48b0-abf0-68a60ae17888", "type": "concept", "title": "Oral explanation"}, {"id": "a3af85f9-cec5-4afb-922a-f580e31b680b", "type": "concept", "title": "Limitations and next steps"}], "description": "Students present the investigation in a lab report or poster and reflect on limitations, ethics, and future work."}]}], "dbBacked": true}$nscljson$::jsonb,
